const ollama = $input.first().json;
const parsed = typeof ollama.response === 'string' ? JSON.parse(ollama.response) : ollama.response;
const allowedRoles = ['WAITER', 'CHEF', 'BARISTA', 'CASHIER', 'KITCHEN HELPER'];
const role = String(parsed.roleNeeded || '').trim().toUpperCase();
const pay = Number(parsed.pay);
return [{ json: {
  title: String(parsed.title || '').trim(),
  description: String(parsed.description || '').trim(),
  requirements: String(parsed.requirements || '').trim(),
  roleNeeded: allowedRoles.includes(role) ? role : '',
  pay: Number.isFinite(pay) && pay > 0 ? pay : null,
  date: String(parsed.date || '').trim(),
  startTime: String(parsed.startTime || '').trim(),
  endTime: String(parsed.endTime || '').trim(),
  location: String(parsed.location || '').trim(),
  assumptions: String(parsed.assumptions || '').trim(),
  source: 'N8N_OLLAMA'
} }];
